// ─── Ratio 查找表 (reg11 索引 → 实际 Ratio) ────────────────────────────
export const RATIO_TABLE: number[] = [
  1.0, 1.2, 1.4, 1.6, 1.8,
  2.0, 2.4, 2.8, 3.2, 3.6,
  4.0, 4.4, 4.8, 5.2, 5.6,
  6.0, 6.4, 6.8, 7.2, 7.6,
  8.0, 8.4, 9.0, 9.6, 10.2,
  10.8, 11.4, 12, 13, 14,
  15, 16, 17, 18, 19,
  20, 22, 24, 26, 30,
  100,
];

/** 查找最接近目标 ratio 的表格索引 (reg11 值) */
export function ratioToIndex(target: number): number {
  let best = 0;
  let bestDiff = Infinity;
  for (let i = 0; i < RATIO_TABLE.length; i++) {
    const d = Math.abs(RATIO_TABLE[i] - target);
    if (d < bestDiff) { bestDiff = d; best = i; }
  }
  return best;
}

/** 根据 ratio 名称 (如 "4:1") 返回索引 */
export function ratioNameToIndex(name: string): number {
  const parts = name.split(':');
  const target = parts.length >= 2 ? parseFloat(parts[0]) : parseFloat(name);
  return isNaN(target) ? 10 : ratioToIndex(target);
}

