// ═══ v12 单块参数替换 (2026-09-23) ═══════════════════════════════════════════
// 用 apk_model_params.md 标注值重编码的结果覆盖 41 个单块型号的 OVERDRIVE_DEFAULTS：
//   knobs(UI 初值) / hidden(DC_ADJ) / allRegs(Pre4 + Drive/DC/Volume + Post4 整图)
// 必须在下面的"系列化物化"之前执行，组合键才会拿到新数据。
for (const [k, d] of Object.entries(PEDAL_DEFAULTS2)) {
  OVERDRIVE_DEFAULTS[k] = { knobs: d.knobs, hidden: d.hidden, allRegs: d.allRegs };
}

// ═══ v14 箱头参数替换 (2026-09-25, P1 箱头参数移植) ══════════════════════════
// 覆盖 78 个箱头 capture 键的 AMP_HEAD_HIDDEN（72-98 整图）与 AMP_HEAD_KNOB_DEFAULTS：
//   · Pre4(74-77) + Post16(83-98) = amp_head_design.md 各箱头真实电路推导（按声明+权威表重编码）
//   · 80 = 设计稿 DC_ADJ（CLEAN 头沿用电路表值）；79 = Drive；81 = Volume（夹在 APK 量程 248-288）
//   · 音色旋钮初值 0.5（noon = 设计曲线本身）；CLEAN 头 GAIN=0 且 allRegs[78]=1（OD 常闭）
// 注意：引擎写 AMP_HEAD_HIDDEN 时会跳过 73/78/82（内部分段旁路）与 79/81（另行写入甜点）；
//       CLEAN 开关键（MODULE_PARAM_MAP['amp-head'].CLEAN）单独写 reg78，PrePEQ(73) 不再被旁路。
// v15 测试轮 (2026-09-26): 只覆盖主键，`_N` 后缀键保留历史 NAM 整图，两份并存。
//   主键   'B&F NAM Marshall JCM800/Marshall JCM800'    -> v14 电路推导值
//   后缀键 'B&F NAM Marshall JCM800/Marshall JCM800_2'  -> 原 NAM 捕获（未被覆盖）
// 后缀键是"同型号第 N 个捕获"，原值互不相同（44 组 100% 不同），此处刻意保留。
// UI 侧 uiTrim.ts 的 KEEP['amp-head'] 已为吉他型号补上 _2 档，下拉可选。
// 回滚：删掉下面那行 if，即恢复 v14 的"全覆盖"行为。
for (const [k, d] of Object.entries(AMP_DEFAULTS2)) {
  if (/_\d+$/.test(k.slice(k.lastIndexOf('/') + 1))) continue;
  AMP_HEAD_HIDDEN[k] = { ...(d.allRegs as Record<number, number>) };
  AMP_HEAD_KNOB_DEFAULTS[k] = { ...(d.knobs as Record<string, number>) };
}

// ═══ 系列化物化: 过载/失真 型号组合键 → OVERDRIVE_DEFAULTS ═══
// 修复 (2026-09-22): seriesData.ts 头注释声称组合键物化进三张表, 但历史上只物化了
// SUB_MODEL_FORMULAS / SUB_MODEL_PRE_EQ (parameterMap.ts 顶层循环), 漏了本表.
// 后果: generatePresetRegisters 对 '中频过载/TS808' 等系列键查不到 → 静默回落 BD-2,
//       出厂预设 OD POST EQ(reg53-56) 全部错成 BD-2 曲线; DIST 兜底键不存在 → 整段缺失.
// 此处按 seriesData 的 models[].key 逐型号物化 (每型号自己的数据, 非系列主型号兜底).
for (const s of SERIES_REGISTRY) {
  for (const m of s.models) {
    const key = seriesModelKey(s, m);
    if (!OVERDRIVE_DEFAULTS[key] && OVERDRIVE_DEFAULTS[m.key]) {
      OVERDRIVE_DEFAULTS[key] = OVERDRIVE_DEFAULTS[m.key];
    }
  }
}